const items = $input.all();
if (items.length === 0) return [];

const headerRowValues = Object.keys(items[0].json);
const dataRows = items.map(item => Object.values(item.json));
const allRows = [headerRowValues, ...dataRows];

function cell(v) { return (v || '').toString().trim(); }

function cleanNotes(raw) {
  if (!raw) return '';
  const idx = raw.indexOf('####');
  if (idx === -1) return raw.trim();
  return raw.substring(0, idx).trim();
}

// Pulls a trailing name out of parentheses, e.g. "...(Ramirez)" -> "Ramirez".
// Returns null if the note doesn't end that way.
function extractTrailingName(text) {
  const match = text.match(/\(([^)]+)\)\s*$/);
  return match ? match[1].trim() : null;
}

const realHeaders = allRows[1].map(h => cell(h));
const output = [];

for (let i = 2; i < allRows.length; i++) {
  const row = allRows[i];
  const bookingIdRaw = cell(row[realHeaders.indexOf('Booking ID')]);
  if (!bookingIdRaw.startsWith('#')) continue;

  const rowObj = {};
  realHeaders.forEach((h, idx) => { rowObj[h] = cell(row[idx]); });

  // Only process guide rows. Excludes driver, "Training Part 2: shadow", and any other
  // crew role FareHarbor might add later. Confirmed with the team: a trainee/shadow is
  // never the sole guide on a booking, so it's always safe to skip every non-guide row.
  const crewRole = (rowObj['Crew role'] || '').toLowerCase();
  if (crewRole !== 'guide') continue;

  // Merge Private Headline and Booking Notes
  const privateHeadline = cleanNotes(rowObj['Private Headline'] || '');
  const bookingNotesRaw = cleanNotes(rowObj['Booking Notes'] || '');
  const booking_notes = [...new Set([privateHeadline, bookingNotesRaw].filter(n => n.trim().length > 0))]
  .join(' | ');

  // FareHarbor's Private Headline field is known to sometimes carry stale text over from a
  // DIFFERENT booking on the same departure -- confirmed cases: "2 non-drinkers (Whitfield)"
  // appearing on Nakamura's booking, and "1 vegetarian... (Ramirez)" appearing on James
  // Delgado's booking. When a note ends in a name, check the RAW (uncleaned) Booking Notes
  // text for this same row -- it still contains "Customers:ActualName" even though
  // cleanNotes strips that whole section out of booking_notes above. If the name doesn't
  // show up there, this note almost certainly belongs to someone else's booking.
  const rawBookingNotesField = rowObj['Booking Notes'] || '';
  const trailingName = extractTrailingName(booking_notes);
  const notesVerified = trailingName === null
    ? true // no name attached, nothing to contradict -- trust it, same as before
    : rawBookingNotesField.toLowerCase().includes(trailingName.toLowerCase());

  const availabilityRaw = rowObj['Availability'] || '';
  const [datePart, timePart] = availabilityRaw.split(' at ');

  output.push({
    json: {
      booking_id: bookingIdRaw,
      item_name: rowObj['Item'],
      crew_member: rowObj['Crew member'],
      cancelled: rowObj['Cancelled?'],
      last_booked_at: rowObj['Last Booked At'],
      cancelled_at: rowObj['Cancelled At'] || null,
      availability_date: (datePart || '').trim(),
      availability_time: (timePart || '').trim(),
      booking_notes: booking_notes,
      notes_verified: notesVerified,
      pax: parseInt(rowObj['# of Pax'], 10) || 0,
      source: 'sheet_paste',
      last_updated: new Date().toISOString()
    }
  });
}

// Deduplicate by booking_id as a safety net against any genuine duplicate guide rows.
const seen = new Set();
const deduped = output.filter(item => {
  if (seen.has(item.json.booking_id)) return false;
  seen.add(item.json.booking_id);
  return true;
});

return deduped;

const parsedBookings = $('Parse FareHarbor CSV Rows').all().map(i => i.json);
const existingBookings = $input.all().map(i => i.json);

const results = parsedBookings.map(booking => {
  const existing = existingBookings.find(e => e.booking_id === booking.booking_id);

  const hasChanged = !existing || (
    String(existing.pax) !== String(booking.pax) ||
    (existing.booking_notes || '') !== (booking.booking_notes || '') ||
    (existing.cancelled || '') !== (booking.cancelled || '') ||
    (existing.crew_member || '') !== (booking.crew_member || '')
  );

  return {
    json: {
      ...booking,
      booking_exists: !!existing,
      booking_changed: hasChanged
    }
  };
});

const anyChanged = results.some(r => r.json.booking_changed);
if (!anyChanged) return [{ json: { no_changes: true } }];

return results;

const allBookings = $('Parse FareHarbor CSV Rows').all().map(i => i.json);

const changedIds = new Set();
try {
  for (const item of $('Changed?').all()) changedIds.add(item.json.booking_id);
} catch (e) {}
try {
  for (const item of $('Create Booking').all()) changedIds.add(item.json.booking_id);
} catch (e) {}
if (changedIds.size === 0) {
  for (const item of $input.all()) changedIds.add(item.json.booking_id);
}

const groups = {};

for (const b of allBookings) {
  const key = `${b.item_name}|||${b.availability_date}|||${b.availability_time}`;
  if (!groups[key]) groups[key] = { tour_name: b.item_name, date: b.availability_date, time: b.availability_time, bookings: [], hasChange: false };
  groups[key].bookings.push(b);
  if (changedIds.has(b.booking_id)) groups[key].hasChange = true;
}

const output = [];

for (const key in groups) {
  const g = groups[key];

  const activeBookings = g.bookings.filter(b => (b.cancelled || '').toLowerCase() !== 'yes');
  const allCancelled = g.bookings.length > 0 && activeBookings.length === 0;
  const totalPax = activeBookings.reduce((sum, b) => sum + (b.pax || 0), 0);

  // Only trust bookings that passed the name-verification check for anything derived from
  // note TEXT -- dietary notes, bourbon upgrades, drink opt-ins. A booking that failed
  // verification almost certainly has another booking's stale Private Headline, not its
  // own, so counting it here would double-count whatever the real booking already reports.
  // Guest counts (totalPax, booking_count above) are untouched -- those come from real
  // booking data, not note text, so they were never part of this bug.
  const verifiedBookings = activeBookings.filter(b => b.notes_verified !== false);

  const notesConcat = verifiedBookings
  .map(b => b.booking_notes)
  .filter(n => n && n.trim().length > 0)
  .map((n, i) => `[Booking ${i + 1}] ${n}`)
  .join(' | ');

  const crewMember = (g.bookings.find(b => b.crew_member && b.crew_member.trim().length > 0) || {}).crew_member || '';

  let bourbonUpgradeCount = 0;
  for (const b of verifiedBookings) {
    const text = b.booking_notes || '';
    const matches = text.matchAll(/(\d+)\s*bourbon upgrade/gi);
    for (const m of matches) {
      bourbonUpgradeCount += parseInt(m[1], 10) || 0;
    }
  }

  let drinkingCount = 0;
  for (const b of verifiedBookings) {
    const text = b.booking_notes || '';
    const matches = text.matchAll(/(\d+)\s*drinking/gi);
    for (const m of matches) {
      drinkingCount += parseInt(m[1], 10) || 0;
    }
  }

  output.push({
    json: {
      tour_name: g.tour_name,
      date: g.date,
      time: g.time,
      total_pax: totalPax,
      booking_count: activeBookings.length,
      notes_concat: notesConcat,
      crew_member: crewMember,
      all_cancelled: allCancelled,
      has_changes: g.hasChange,
      bourbon_upgrade_count: bourbonUpgradeCount,
      drinking_count: drinkingCount
    }
  });
}

return output;

const items = $input.all();

function rowValues(rowJson) {
  const { row_number, ...rest } = rowJson;
  return Object.values(rest);
}

// Row 1 of the sheet became this read's own field key names, not a
// data row - so it never shows up in items at all. Object.keys() on
// any item recovers those original key names, which are exactly row
// 1's original cell text. The content doesn't matter here (it's just
// this tour's title), but a placeholder needs to sit at position 0 so
// every real row after it lines up correctly.
const { row_number: _drop, ...firstItemKeys } = items[0].json;
const headerRowValues = Object.keys(firstItemKeys);

const dataRows = items.map(item => rowValues(item.json));
const allRows = [headerRowValues, ...dataRows];

function findSection(rows, markerName) {
  const startIdx = rows.findIndex(r => (r[0] || '').toString().trim().toUpperCase() === markerName);
  if (startIdx === -1) return [];
  const headerRow = rows[startIdx + 1] || [];
  const result = [];
  for (let i = startIdx + 2; i < rows.length; i++) {
    const row = rows[i];
    const isBlank = !row || row.every(c => !c || c.toString().trim() === '');
    const isNextMarker = row && ['STOPS', 'MENU', 'SUBSTITUTIONS'].includes((row[0] || '').toString().trim().toUpperCase());
    if (isBlank || isNextMarker) break;
    const obj = {};
    headerRow.forEach((h, idx) => { obj[(h || '').toString().trim()] = (row[idx] || '').toString().trim(); });
    result.push(obj);
  }
  return result;
}

return { json: { stops: findSection(allRows, 'STOPS'), menu_items: findSection(allRows, 'MENU'), substitutions: findSection(allRows, 'SUBSTITUTIONS') } };

const items = $input.all();

function rowValues(rowJson) {
  const { row_number, ...rest } = rowJson;
  return Object.values(rest);
}

// Row 1 of the sheet became this read's own field key names, not a
// data row - so it never shows up in items at all. Object.keys() on
// any item recovers those original key names, which are exactly row
// 1's original cell text. The content doesn't matter here (it's just
// this tour's title), but a placeholder needs to sit at position 0 so
// every real row after it lines up correctly.
const { row_number: _drop, ...firstItemKeys } = items[0].json;
const headerRowValues = Object.keys(firstItemKeys);

const dataRows = items.map(item => rowValues(item.json));
const allRows = [headerRowValues, ...dataRows];

function findSection(rows, markerName) {
  const startIdx = rows.findIndex(r => (r[0] || '').toString().trim().toUpperCase() === markerName);
  if (startIdx === -1) return [];
  const headerRow = rows[startIdx + 1] || [];
  const result = [];
  for (let i = startIdx + 2; i < rows.length; i++) {
    const row = rows[i];
    const isBlank = !row || row.every(c => !c || c.toString().trim() === '');
    const isNextMarker = row && ['STOPS', 'MENU', 'SUBSTITUTIONS'].includes((row[0] || '').toString().trim().toUpperCase());
    if (isBlank || isNextMarker) break;
    const obj = {};
    headerRow.forEach((h, idx) => { obj[(h || '').toString().trim()] = (row[idx] || '').toString().trim(); });
    result.push(obj);
  }
  return result;
}

return { json: { stops: findSection(allRows, 'STOPS'), menu_items: findSection(allRows, 'MENU'), substitutions: findSection(allRows, 'SUBSTITUTIONS') } };

const departures = $('Group By Departure').all().map(i => i.json).filter(d => !d.all_cancelled);

const tourTabs = {
  'cellar row: wine & food pairing tour': $('Parse Cellar Row Sections').first().json,
  "shadow street: murder, crime, & ghost tour of rivertown": $('Parse Shadow Street Sections').first().json,
  'echoes of the speakeasy: ghosts, cocktails, & bites tour': $('Parse Speakeasy Sections').first().json,
  'secrets of the arts quarter: food & history tour': $('Parse Secrets of the Arts Quarter Sections').first().json,
  'rivertown legends: downtown heritage food & history tour': $('Parse Rivertown Legends Sections').first().json,
  'historic walking tour of old elm district: food, spirits, history & architecture': $('Parse Old Elm District Sections').first().json,
  'the heritage trolley: distillery tour, tasting rooms & spirits experiences': $('Parse Heritage Trolley Sections').first().json
};

function getDayOfWeek(dateStr) {
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const d = new Date(dateStr + 'T12:00:00');
  return days[d.getDay()];
}

function pickStop(stops, restaurantName, departureDay) {
  const candidates = stops.filter(s =>
    (s.restaurant_name || '').trim().toLowerCase() === restaurantName.trim().toLowerCase()
  );
  const dayMatch = candidates.find(s =>
    (s.day_of_week || '').trim().toLowerCase() === departureDay.toLowerCase()
  );
  if (dayMatch) return dayMatch;
  return candidates.find(s =>
    !s.day_of_week || s.day_of_week.trim() === '' || s.day_of_week.trim().toLowerCase() === 'all'
  );
}

const output = [];

for (const dep of departures) {
  const tabData = tourTabs[(dep.tour_name || '').trim().toLowerCase()];
  if (!tabData) continue;

  const departureDay = getDayOfWeek(dep.date);
  const addedRestaurants = new Set();
  const sortedStops = [...tabData.stops].sort((a, b) =>
    (parseInt(a.stop_order) || 0) - (parseInt(b.stop_order) || 0)
  );

  const uniqueRestaurants = [];
  for (const stop of sortedStops) {
    const key = (stop.restaurant_name || '').trim().toLowerCase();
    if (!addedRestaurants.has(key)) {
      addedRestaurants.add(key);
      uniqueRestaurants.push(stop.restaurant_name);
    }
  }

  for (const restaurantName of uniqueRestaurants) {
    const stop = pickStop(tabData.stops, restaurantName, departureDay);
    if (!stop) continue;

    const restaurantMenuItems = tabData.menu_items.filter(m =>
      (m.restaurant_name || '').trim().toLowerCase() === restaurantName.trim().toLowerCase()
    );

    const i = output.length;
    output.push({
      json: {
        ...dep,
        restaurant_name: stop.restaurant_name,
        contact_email: stop.contact_email,
        stop_order: stop.stop_order,
        minutes_after_start: stop.minutes_after_start,
        has_menu: restaurantMenuItems.length > 0,
        menu_items: restaurantMenuItems,
        substitutions: tabData.substitutions.filter(s =>
          (s.restaurant_name || '').trim().toLowerCase() === restaurantName.trim().toLowerCase()
        )
      }
    });
  }
}

return output;

const original = $('Expand Departure To Stops').item.json;
const totalPax = original.total_pax;
const flags = ($json.output && $json.output.flags) || [];
const menuItems = original.menu_items || [];
const subs = original.substitutions || [];

const isArtsQuarterTour = (original.tour_name || '').trim().toLowerCase() === 'secrets of the arts quarter: food & history tour';
const isLegendsTour = (original.tour_name || '').trim().toLowerCase() === "rivertown legends: downtown heritage food & history tour";
const drinkingCount = original.drinking_count || 0;

const veganFlag = flags.find(f => (f.diet_type || '').toLowerCase() === 'vegan');
const veganWarning = veganFlag
  ? `⚠️ VEGAN: ${veganFlag.count} guest(s) marked vegan — this tour cannot accommodate vegan, needs a human to follow up before the tour.`
  : null;

function calcTotal(guestCount, split) {
  return Math.ceil(guestCount * (parseFloat(split) || 1));
}

function calcArrivalTime(tourTime, minutesAfter) {
  const [timePart, period] = tourTime.split(' ');
  const [h, m] = timePart.split(':').map(Number);
  let total = (h % 12 + (period === 'PM' ? 12 : 0)) * 60 + m + (parseInt(minutesAfter) || 0);
  const arrH = Math.floor(total / 60) % 24;
  const arrM = total % 60;
  const arrPeriod = arrH >= 12 ? 'PM' : 'AM';
  const display = arrH % 12 || 12;
  return `${display}:${arrM.toString().padStart(2, '0')} ${arrPeriod}`;
}

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T12:00:00');
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  return `${days[d.getDay()]} ${d.getMonth() + 1}/${d.getDate()}`;
}

// Strips a leading "1/2 " or "1/2 of " off an item name before comparing, so a menu tab
// using the literal "1/2 X" naming convention and a substitutions tab still referencing
// the old "X" name (or vice versa) are still recognized as the same item. This is what
// broke the Swizzle/O'Shea's/Pin+Proof alcohol substitutions -- the menu tabs got the
// "1/2 " prefix added during the Aug 14 rename, the substitutions tabs didn't.
function normalizeItemName(name) {
  return (name || '')
    .toLowerCase()
    .trim()
    .replace(/^1\/2\s+(of\s+)?/, '');
}

function reducedCountFor(itemName) {
  let reduced = 0;
  const normalizedItemName = normalizeItemName(itemName);
  for (const flag of flags) {
    const type = (flag.diet_type || '').toLowerCase();
    if (type === 'vegan' || type === 'other') continue;
    if (type === 'alcohol' && isArtsQuarterTour) continue;
    const sub = subs.find(s => (s.diet_type || '').toLowerCase() === type);
    if (!sub || !sub.replaces_item) continue;
    const replacedItems = sub.replaces_item.split(',').map(s => normalizeItemName(s));
    if (replacedItems.includes(normalizedItemName)) {
      reduced += flag.count || 0;
    }
  }
  return reduced;
}

const orderLines = [];
const rawSubLines = [];

for (const item of menuItems) {
  const split = parseFloat(item.per_person_split) || 1;
  const category = (item.category || '').toLowerCase();
  let guestCount;
  if (isLegendsTour && category === 'drink') {
    guestCount = drinkingCount;
  } else {
    const reduced = reducedCountFor(item.item_name);
    guestCount = Math.max(totalPax - reduced, 0);
  }
  if (guestCount > 0) {
    orderLines.push(`${calcTotal(guestCount, split)} ${item.item_name}`);
  }
}

for (const flag of flags) {
  const type = (flag.diet_type || '').toLowerCase();
  if (type === 'vegan' || type === 'other') continue;
  if (type === 'alcohol' && isArtsQuarterTour) continue;
  const sub = subs.find(s => (s.diet_type || '').toLowerCase() === type);
  if (!sub || !sub.substitution_item || sub.substitution_item.toLowerCase() === 'none') continue;
  const replacedItem = menuItems.find(m => normalizeItemName(m.item_name) === normalizeItemName(sub.replaces_item));
  const split = replacedItem ? (parseFloat(replacedItem.per_person_split) || 1) : 1;
  const label = sub.note ? `${sub.substitution_item} (${sub.note})` : sub.substitution_item;
  rawSubLines.push({ count: flag.count || 0, split, label });
}

const subMap = {};
for (const s of rawSubLines) {
  if (!subMap[s.label]) subMap[s.label] = { count: 0, split: s.split };
  subMap[s.label].count += s.count;
}
const substitutionLines = Object.entries(subMap).map(([label, { count, split }]) =>
  `${calcTotal(count, split)} ${label}`
);

const otherNotes = flags
  .filter(f => {
    const type = (f.diet_type || '').toLowerCase();
    if (type === 'vegan') return false;
    if (type === 'alcohol' && isArtsQuarterTour) return false;
    if (type === 'other') return true;
    const sub = subs.find(s => (s.diet_type || '').toLowerCase() === type);
    return !sub || !sub.substitution_item || sub.substitution_item.toLowerCase() === 'none';
  })
  .map(f => {
    const count = f.count || 0;
    const guestWord = count === 1 ? 'guest' : 'guests';
    return `${count} ${guestWord}: ${f.detail}`;
  });

const bourbonUpgradeCount = original.bourbon_upgrade_count || 0;
const bourbonUpgradeNote = bourbonUpgradeCount > 0
  ? `${bourbonUpgradeCount} bourbon upgrade${bourbonUpgradeCount === 1 ? '' : 's'}`
  : null;

const arrivalTime = calcArrivalTime(original.time, original.minutes_after_start);
const formattedDate = formatDate(original.date);

return {
  json: {
    ...original,
    order_lines: orderLines,
    substitution_lines: substitutionLines,
    other_dietary_notes: otherNotes,
    vegan_warning: veganWarning,
    bourbon_upgrade_note: bourbonUpgradeNote,
    arrival_time: arrivalTime,
    formatted_date: formattedDate
  }
};

const original = $('Expand Departure To Stops').item.json;

function toFraction(decimal) {
  if (decimal >= 1) return null;
  const common = [
    [1/2,'1/2'],[1/3,'1/3'],[2/3,'2/3'],[1/4,'1/4'],
    [3/4,'3/4'],[1/5,'1/5'],[2/5,'2/5'],[3/5,'3/5'],
    [4/5,'4/5'],[1/6,'1/6'],[5/6,'5/6'],[1/8,'1/8'],
    [3/8,'3/8'],[5/8,'5/8'],[7/8,'7/8']
  ];
  for (const [val, str] of common) {
    if (Math.abs(decimal - val) < 0.01) return str;
  }
  return null;
}

function calcArrivalTime(tourTime, minutesAfter) {
  const [timePart, period] = tourTime.split(' ');
  const [h, m] = timePart.split(':').map(Number);
  let total = (h % 12 + (period === 'PM' ? 12 : 0)) * 60 + m + (parseInt(minutesAfter) || 0);
  const arrH = Math.floor(total / 60) % 24;
  const arrM = total % 60;
  const arrPeriod = arrH >= 12 ? 'PM' : 'AM';
  const display = arrH % 12 || 12;
  return `${display}:${arrM.toString().padStart(2, '0')} ${arrPeriod}`;
}

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T12:00:00');
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  return `${days[d.getDay()]} ${d.getMonth() + 1}/${d.getDate()}`;
}

const arrivalTime = calcArrivalTime(original.time, original.minutes_after_start);
const formattedDate = formatDate(original.date);

return {
  json: {
    ...original,
    order_lines: [],
    substitution_lines: [],
    other_dietary_notes: [],
    vegan_warning: null,
    arrival_time: arrivalTime,
    formatted_date: formattedDate
  }
};

parameters.text:
=You are writing a short internal alert for Rivertown Food Tours staff.

A tour group has been fully cancelled. Write a brief, professional notice for staff, clearly listing which restaurants were scheduled to be visited so they can be notified directly.

Details:
- Tour name: {{ $json.tour_name }}
- Date: {{ $json.date }}
- Time: {{ $json.time }}
- Guide: {{ $json.crew_member }}
- Restaurants scheduled: {{ $json.restaurant_names }}

Instructions:
- Keep it to one short paragraph
- Clearly name each restaurant listed above so staff know who to contact
- Do not include any order details, headcounts, or dietary notes
- Sign off with "Rivertown Food Tours"
- Return a JSON object with two fields: "subject" and "body"
- The body must be in HTML using <p> tags
- Do not include any text outside the JSON object

