const allStops = $input.all().map(i => i.json);
const restaurantDrafts = $('Get Restaurant Drafts').all().map(i => i.json);

const groups = {};

for (const stop of allStops) {
  if (stop.all_cancelled) continue;
  const key = (stop.contact_email || '').trim().toLowerCase();
  if (!groups[key]) {
    groups[key] = {
      restaurant_name: stop.restaurant_name,
      contact_email: stop.contact_email,
      has_changes: false,
      departures: []
    };
  }
  if (stop.has_changes) groups[key].has_changes = true;
  groups[key].departures.push({
    tour_name: stop.tour_name,
    date: stop.date,
    time: stop.time,
    formatted_date: stop.formatted_date,
    arrival_time: stop.arrival_time,
    total_pax: stop.total_pax,
    crew_member: stop.crew_member,
    has_changes: stop.has_changes,
    all_cancelled: stop.all_cancelled,
    order_lines: stop.order_lines || [],
    substitution_lines: stop.substitution_lines || [],
    other_dietary_notes: stop.other_dietary_notes || [],
    vegan_warning: stop.vegan_warning || null,
    bourbon_upgrade_note: stop.bourbon_upgrade_note || null
  });
}

const output = [];

for (const key in groups) {
  const g = groups[key];
  if (!g.has_changes) continue;
  if (g.departures.length === 0) continue;

  g.departures.sort((a, b) => new Date(a.date) - new Date(b.date));

  const earliestDate = new Date(g.departures[0].date + 'T12:00:00');
  const dayOfWeek = earliestDate.getDay();
  const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
  const monday = new Date(earliestDate);
  monday.setDate(earliestDate.getDate() + daysToMonday);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  const weekRange = `${monday.getMonth() + 1}/${monday.getDate()}-${sunday.getMonth() + 1}/${sunday.getDate()}`;

  const signatureParts = g.departures.map(d =>
