const sentRecords = $('Check Cancellation Sent?').all().map(i => i.json).filter(j => j && j.departure_key);
const sentKeys = new Set(sentRecords.map(r => r.departure_key));

const parsedTabs = $('Parse Cancelled Tour Sections').all().map(i => i.json);
const tabByTourName = {};
