  tabByTourName[(t.tour_name || '').trim().toLowerCase()] = t;
}

function getDayOfWeek(dateStr) {
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const d = new Date(dateStr + 'T12:00:00');
  return days[d.getDay()];
}

function pickStop(stops, restaurantName, departureDay) {
  const candidates = stops.filter(s => (s.restaurant_name || '').trim().toLowerCase() === restaurantName.trim().toLowerCase());
  const dayMatch = candidates.find(s => (s.day_of_week || '').trim().toLowerCase() === departureDay.toLowerCase());
  if (dayMatch) return dayMatch;
  return candidates.find(s => !s.day_of_week || s.day_of_week.trim() === '' || s.day_of_week.trim().toLowerCase() === 'all');
}

