for (const dep of allCancelledDeps) {
  const departureKey = `${dep.tour_name}|||${dep.date}|||${dep.time}`.replace(/[^a-zA-Z0-9|]/g, '_');
  if (sentKeys.has(departureKey)) continue;

  let names = [];
  const tabData = tabByTourName[(dep.tour_name || '').trim().toLowerCase()];
  if (tabData) {
    const departureDay = getDayOfWeek(dep.date);
    const seen = new Set();
    for (const stop of tabData.stops) {
      const key = (stop.restaurant_name || '').trim().toLowerCase();
      if (seen.has(key)) continue;
      const matchStop = pickStop(tabData.stops, stop.restaurant_name, departureDay);
      if (matchStop) { seen.add(key); names.push(stop.restaurant_name); }
    }
  }

  output.push({
    json: {
      ...dep,
      departure_key: departureKey,
      restaurant_names: names.length > 0
        ? names.join(', ')
        : 'UNAVAILABLE — restaurant list could not be determined for this run. Check FareHarbor manually and notify every restaurant scheduled for this tour.'
    }
  });
}

return output;

